import { Component, OnInit } from '@angular/core';
import { ActivatedRoute } from '@angular/router';
import { Speaker } from '@app/shared/interfaces/speaker';
import { appConfig } from '@app/app.config';

@Component({
  selector: 'app-speakers',
  templateUrl: './speakers.component.html',
})
export class SpeakersComponent implements OnInit {
  constructor(
    private activatedRoute: ActivatedRoute,
  ) {
  }

  year = appConfig.year;
  showSpeakers = appConfig.showSpeakers;
  speakers:Speaker[] = [];

  async ngOnInit() {
    const allSessionizeData = await this.activatedRoute.snapshot.data["speakers"];

    this.speakers = allSessionizeData.speakers;
  }
}
